/**
 * Per-secret changes of `update_connection`; a missing field keeps the stored secret.
 */
export type SecretsUpdateInput = { db_password?: SecretChangeInput; ssh_password?: SecretChangeInput; ssh_key_passphrase?: SecretChangeInput }
export type ServerInfo = { kind: DbKind; variant: ServerVariant; version: [number, number, number]; version_string: string }
export type ServerVariant = "MySql57" | "MySql8" | "MariaDb" | "Postgres"
/**
 * An entry of the import file that cannot be imported at all.
 */
export type SkippedItem = { name: string; reason: string }
export type Snippet = { id: string; 
/**
 * What the user types to trigger it; unique, case-insensitively.
 */
prefix: string; label: string; 
/**
 * Monaco snippet syntax (`${1:placeholder}`, `$0`).
 */
body: string; description: string; created_at: string; updated_at: string }
export type SnippetInput = { prefix: string; label: string; body: string; description: string }
export type SortDir = "asc" | "desc"
/**
 * Server-side `ORDER BY` of one column (which must be a column of the object).
 */
export type SortSpec = { column: string; dir: SortDir }
export type SshAuth = "password" | "key"
export type SshConfig = { version?: number; host: string; port: number; user: string; auth: SshAuth; key_path: string | null }
export type SslConfig = { version?: number; mode: SslMode; ca_path: string | null; cert_path: string | null; key_path: string | null }
export type SslMode = "disable" | "prefer" | "require" | "verify_ca" | "verify_full"
/**
 * How long one completed stage of the connect pipeline took.
 */
export type StageTiming = { stage: ConnectStage; 
/**
 * Exported as a JS number (milliseconds).
 */
ms: number }
/**
 * One statement of an applied plan.
 */
export type StmtApply = { 
/**
 * The edit's index in the `EditSet`.
 */
index: number; 
/**
 * Rows the statement matched.
 */
affected: number | null; error: AppError | null; 
/**
 * It matched no row (or not the rows expected): the row changed or went away since
 * it was loaded.
 */
conflict: boolean }
export type StmtKindLabel = "read" | "write" | "ddl" | "transaction" | "other"
/**
 * Why a run is being stopped.
 */
export type StopCause = 
/**
 * The user pressed Stop (or closed the tab / connection).
 */
"user" | 
/**
 * The statement's time limit expired.
 */
"timeout"
/**
 * Why a run ended before its last statement.
 */
export type StopReason = 
/**
 * Statement `index` failed.
 */
{ kind: "error"; index: number } | 
/**
 * The user stopped the run.
 */
{ kind: "cancelled" } | 
/**
 * The PostgreSQL transaction is aborted: only `ROLLBACK [TO]` / `COMMIT` may run.
 */
{ kind: "tx_aborted" } | 
/**
 * A statement finished after its timeout; the rest was not run.
 */
{ kind: "late_completion" } | 
/**
 * The session's `sql_mode` now splits the rest differently, starting at statement
 * `index`: "sql_mode changed; run the remaining statements again".
 */
{ kind: "dialect_changed"; index: number }
/**
 * The transaction of a query tab, for the status bar and the idle-transaction warning.
 */
export type TabTxInfo = { state: TxState; 
/**
 * When the open transaction began (Unix epoch, milliseconds; as seen by the app:
 * the start of the run or the `BEGIN` that opened it). `None` when no transaction
 * is open, or its start is not known.
 */
since_ms: number | null; 
/**
 * Statements run in the open transaction (0 when none is open).
 */
statements: number }
export type TableDataPage = { columns: ColumnMeta[]; 
/**
 * At most `limit` rows, starting at `offset` (fewer when `size_capped`).
 */
rows: Value[][]; 
/**
 * Whether a row follows this page (the next page starts at `offset + rows.len()`).
 */
has_more: boolean; 
/**
 * Text / JSON cells cut to 64 KB.
 */
truncated_cells: number; 
/**
 * Where those cells are: `[row, column]` indexes into `rows`.
 */
truncated: ([number, number])[]; 
/**
 * The page reached its byte budget: rows were left for the next page.
 */
size_capped: boolean; 
/**
 * Without an explicit sort: the primary key columns the page is ordered by (stable
 * paging); empty when there is no primary key or a sort was given.
 */
key_order: string[]; 
/**
 * PostgreSQL tables the data view may edit: each row's `xmin`, in row order (the
 * row version an edit is guarded with). Null otherwise.
 */
row_versions: string[] | null; 
/**
 * Key columns a `SELECT *` does not return (MySQL `INVISIBLE`), read explicitly;
 * not part of `columns`.
 */
hidden_key: ColumnMeta[]; 
/**
 * Their values, one entry per row of `rows` (empty without `hidden_key`).
 */
hidden_key_values: Value[][]; elapsed_ms: number }
export type TableDetail = { object: ObjectRef; columns: ColumnDetail[]; primary_key: IndexDetail | null; indexes: IndexDetail[]; foreign_keys: ForeignKeyDetail[]; checks: CheckDetail[]; triggers: TriggerDetail[]; options: TableOptions; 
/**
 * Exported as JS numbers: estimates and sizes stay far below 2^53.
 */
row_estimate: number | null; size_bytes: number | null; comment: string | null }
export type TableOptions = { engine: string | null; collation: string | null; tablespace: string | null; partitioned_by: string | null; system_versioned: boolean }
export type TableRowCount = { 
/**
 * Exact `COUNT(*)`.
 */
rows: number; elapsed_ms: number }
/**
 * What the user asked to run. Offsets are UTF-16 code units into the editor text.
 */
export type Target = { Cursor: number } | { Selection: [number, number] } | "All"
export type Tree = { groups: Group[]; connections: ConnectionSummary[] }
export type TriggerDetail = { name: string; timing: string; event: string }
export type TxAction = "Commit" | "Rollback"
/**
 * How a query tab commits (spec §4.2e). `Auto`: every statement commits on its own
 * unless the user opens a transaction. `Manual`: before every statement that needs a
 * transaction (a write; PostgreSQL DDL that can run in one) while none is open, the run
 * begins one (`BEGIN` / `START TRANSACTION`), which the user then commits or rolls back
 * (`query_tx`).
 */
export type TxMode = "Auto" | "Manual"
/**
 * Transaction state of a session as the query layer sees it.
 */
export type TxState = 
/**
 * No transaction is open (autocommit).
 */
"idle" | 
/**
 * A transaction is open (or MySQL `autocommit = 0` is in effect).
 */
"active" | 
/**
 * PostgreSQL only: a statement failed inside a transaction block; the server
 * rejects everything but `ROLLBACK [TO SAVEPOINT]` / `COMMIT` until it ends.
 */
"aborted"
/**
 * Why it changes every row.
 */
export type UnboundedReason = 
/**
 * No WHERE at depth 0 (or one with an empty condition).
 */
"no_where" | 
/**
 * A trivially-true WHERE (`WHERE 1`, `1=1`, `true`, `'a'='a'`, `id = id`).
 */
"always_true" | 
/**
 * `TRUNCATE` has no WHERE at all.
 */
"truncate"
/**
 * One unbounded write of a statement.
 */
export type UnboundedWrite = { op: WriteOp; reason: UnboundedReason; 
/**
 * The target table(s) as written (quotes kept), comma-separated; empty when the
 * statement names none.
 */
table: string }
export type Value = { t: "Null" } | { t: "Bool"; v: boolean } | { t: "Int"; v: JsInteger } | { t: "UInt"; v: JsInteger } | { t: "Float"; v: number } | { t: "Decimal"; v: string } | { t: "Text"; v: string } | { t: "Json"; v: string } | { t: "Uuid"; v: string } | { t: "Bytes"; v: { 
/**
 * A byte length; far below 2^53 in practice, so a plain number.
 */
len: number; preview: number[] } } | { t: "Date"; v: string } | { t: "Time"; v: string } | { t: "DateTime"; v: string } | { t: "TimestampTz"; v: string } | { t: "Array"; v: Value[] } | { t: "Other"; v: { type_name: string; text: string } }
export type Verdict = "allow" | "confirm" | "block"
/**
 * The statement that changes every row.
 */
export type WriteOp = "update" | "delete" | "truncate"

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
